STYLE = ("Use reference images 1 and 2 ONLY for drawing style: clean editorial comic illustration, even medium-weight black outlines, "
         "flat muted colours, minimal cel shading, calm simple backgrounds, period-accurate details. Do not copy any person or scene from them. ")
CHAR = {"R": "Rasputin must match the man in the Rasputin reference image: long dark hair parted in the middle, long thick dark beard, piercing pale eyes, black peasant tunic with a belt, small cross. ",
        "F": "Tsar Nicholas II, Empress Alexandra and the little Tsarevich Alexei must match the faces in the imperial family reference image. "}
REF = {"S1": "5d5f0d40-6d72-4644-b3e1-0f824c81becb", "S2": "8e1e1260-e11b-4083-a4d6-5f15a0a4008c",
       "R": "1a4d1ac5-bef0-4ecb-a629-0fdf33936294", "F": "589dd8e5-c035-43d8-b6cd-20b3cf38da21"}
def request(i):
    p, l, fr, refs, d = S[i-1]
    if "Rasputin" in d and "R" not in refs: refs += "R"
    if any(k in d for k in ("Empress", "Tsar Nicholas", "Tsarevich")) and "F" not in refs: refs += "F"
    medias = [{"role": "image_references", "value": REF["S1"]}, {"role": "image_references", "value": REF["S2"]}]
    extra = ""
    for r in refs:
        medias.append({"role": "image_references", "value": REF[r]}); extra += CHAR[r]
    import re
    text = " Any words or numbers written in the scene must be exactly as given." if re.search(r"'[A-Z0-9][^']*'", d) else " No text, no captions, no title."
    return {"index": i, "params": {"model": "gpt_image_2_6", "aspect_ratio": "16:9", "medias": medias,
            "prompt": STYLE + extra + "SCENE (16:9): " + d + "." + text}}
if __name__ == "__main__":
    print(len(S))
